package tw.com.tft.documentscanner.view;import android.content.*;import android.graphics.*;import android.util.*;import android.view.*;import androidx.annotation.Nullable;import java.util.*;import tw.com.tft.documentscanner.imaging.DocumentDetector;public class CropView extends View{private Bitmap b;private final Paint ip=new Paint(3),lp=new Paint(1),hp=new Paint(1),shade=new Paint(),cross=new Paint(1);private final Matrix mx=new Matrix();private final RectF ir=new RectF();private float[]c=DocumentDetector.safeInset();private int active=-1;private float lx,ly;private final float precision=.36f;private float tr,hr,mr;public CropView(Context x){super(x);init();}public CropView(Context x,@Nullable AttributeSet a){super(x,a);init();}private void init(){float d=getResources().getDisplayMetrics().density;tr=44*d;hr=10*d;mr=64*d;lp.setStyle(Paint.Style.STROKE);lp.setStrokeWidth(3*d);lp.setColor(Color.rgb(33,219,165));hp.setColor(Color.WHITE);shade.setColor(0x88000000);cross.setColor(Color.RED);cross.setStrokeWidth(2*d);setLayerType(LAYER_TYPE_SOFTWARE,null);}public void setBitmap(Bitmap x){b=x;matrix();invalidate();}public void setCornersNormalized(float[]x){c=x!=null&&x.length==8?Arrays.copyOf(x,8):DocumentDetector.safeInset();invalidate();}public float[]getCornersNormalized(){return Arrays.copyOf(c,8);}protected void onSizeChanged(int w,int h,int ow,int oh){matrix();}private void matrix(){if(b==null||getWidth()==0)return;float s=Math.min(getWidth()/(float)b.getWidth(),getHeight()/(float)b.getHeight()),dw=b.getWidth()*s,dh=b.getHeight()*s,dx=(getWidth()-dw)/2,dy=(getHeight()-dh)/2;mx.reset();mx.postScale(s,s);mx.postTranslate(dx,dy);ir.set(dx,dy,dx+dw,dy+dh);}protected void onDraw(Canvas cv){cv.drawColor(Color.rgb(14,16,18));if(b==null)return;cv.drawBitmap(b,mx,ip);PointF[]p=pts(),h=handles(p);Path q=new Path();q.moveTo(p[0].x,p[0].y);for(int i=1;i<4;i++)q.lineTo(p[i].x,p[i].y);q.close();Path out=new Path();out.addRect(ir,Path.Direction.CW);out.op(q,Path.Op.DIFFERENCE);cv.drawPath(out,shade);cv.drawPath(q,lp);for(int i=0;i<8;i++){cv.drawCircle(h[i].x,h[i].y,i==active?hr*1.35f:hr,hp);cv.drawCircle(h[i].x,h[i].y,i==active?hr*1.35f:hr,lp);}if(active>=0)mag(cv,h[active]);}private PointF[]pts(){PointF[]p=new PointF[4];for(int i=0;i<4;i++)p[i]=new PointF(ir.left+c[i*2]*ir.width(),ir.top+c[i*2+1]*ir.height());return p;}private PointF[]handles(PointF[]p){return new PointF[]{p[0],p[1],p[2],p[3],mid(p[0],p[1]),mid(p[3],p[2]),mid(p[0],p[3]),mid(p[1],p[2])};}private PointF mid(PointF a,PointF b){return new PointF((a.x+b.x)/2,(a.y+b.y)/2);}public boolean onTouchEvent(MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:active=near(e.getX(),e.getY());if(active<0)return false;lx=e.getX();ly=e.getY();return true;case MotionEvent.ACTION_MOVE:if(active<0)return false;float dx=(e.getX()-lx)*precision/Math.max(1,ir.width()),dy=(e.getY()-ly)*precision/Math.max(1,ir.height());lx=e.getX();ly=e.getY();move(active,dx,dy);invalidate();return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:active=-1;invalidate();return true;}return true;}private int near(float x,float y){PointF[]h=handles(pts());int z=-1;float bd=1e9f;for(int i=0;i<8;i++){float d=(float)Math.hypot(x-h[i].x,y-h[i].y);if(d<tr&&d<bd){bd=d;z=i;}}return z;}private void move(int h,float dx,float dy){if(h<4){c[h*2]=cl(c[h*2]+dx);c[h*2+1]=cl(c[h*2+1]+dy);}else if(h==4){c[1]=cl(c[1]+dy);c[3]=cl(c[3]+dy);}else if(h==5){c[5]=cl(c[5]+dy);c[7]=cl(c[7]+dy);}else if(h==6){c[0]=cl(c[0]+dx);c[6]=cl(c[6]+dx);}else{c[2]=cl(c[2]+dx);c[4]=cl(c[4]+dx);}}private float cl(float v){return Math.max(.001f,Math.min(.999f,v));}private void mag(Canvas cv,PointF t){float mar=14*getResources().getDisplayMetrics().density,cx=t.x<getWidth()/2f?getWidth()-mr-mar:mr+mar,cy=mr+mar,nx=(t.x-ir.left)/ir.width(),ny=(t.y-ir.top)/ir.height(),bx=nx*b.getWidth(),by=ny*b.getHeight(),sr=mr/3.6f/Math.max(.001f,ir.width()/b.getWidth());RectF src=new RectF(Math.max(0,bx-sr),Math.max(0,by-sr),Math.min(b.getWidth(),bx+sr),Math.min(b.getHeight(),by+sr)),dst=new RectF(cx-mr,cy-mr,cx+mr,cy+mr);cv.save();Path p=new Path();p.addCircle(cx,cy,mr,Path.Direction.CW);cv.clipPath(p);cv.drawBitmap(b,src,dst,ip);cv.restore();cv.drawCircle(cx,cy,mr,lp);cv.drawLine(cx-14,cy,cx+14,cy,cross);cv.drawLine(cx,cy-14,cx,cy+14,cross);}}